{
  "name": "NI计数器输出模块",
  "name_en": "NI Counter Output Module",
  "manufacturer": "National Instruments",
  "description": "这是一类美国国家仪器（NI）的数据采集计数器/定时器输出硬件，用于产生可设定延时、高电平时间、低电平时间和周期的脉冲序列，并可配置外部触发源与触发沿。它常用于实验中的时序控制、同步触发、脉冲信号产生以及与其他仪器的联动。",
  "description_en": "This is a National Instruments data acquisition counter/timer output device used to generate pulse sequences with configurable initial delay, high time, low time, and period, with support for external trigger source and trigger edge selection. It is commonly used in laboratories for timing control, synchronization, trigger generation, and coordination with other instruments.",
  "tag_hints": [
    "NI DAQ",
    "counter output",
    "timer pulse generation",
    "trigger synchronization",
    "digital pulse train",
    "laboratory timing control"
  ],
  "actions": [
    {
      "action_name": "auto-setup",
      "description": "初始化计数器输出设备的配置项。",
      "description_en": "Initialize the configuration parameters for the counter output device."
    },
    {
      "action_name": "auto-connect",
      "description": "连接到NI计数器输出硬件。",
      "description_en": "Connect to the NI counter output hardware."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与NI计数器输出硬件的连接。",
      "description_en": "Disconnect from the NI counter output hardware."
    },
    {
      "action_name": "auto-start",
      "description": "启动计数器输出信号。",
      "description_en": "Start the counter output signal."
    },
    {
      "action_name": "auto-stop",
      "description": "停止计数器输出信号。",
      "description_en": "Stop the counter output signal."
    },
    {
      "action_name": "auto-update_channels",
      "description": "刷新可用的NI设备、输出端子和触发端子列表。",
      "description_en": "Refresh the list of available NI devices, output terminals, and trigger terminals."
    },
    {
      "action_name": "auto-get_initial_delay_chan1",
      "description": "获取通道1的初始延时。",
      "description_en": "Get the initial delay of channel 1."
    },
    {
      "action_name": "auto-get_initial_delay_chan2",
      "description": "获取通道2的初始延时。",
      "description_en": "Get the initial delay of channel 2."
    },
    {
      "action_name": "auto-get_high_time1",
      "description": "获取通道1的高电平时间。",
      "description_en": "Get the high time of channel 1."
    },
    {
      "action_name": "auto-get_low_time1",
      "description": "获取通道1的低电平时间。",
      "description_en": "Get the low time of channel 1."
    },
    {
      "action_name": "auto-get_high_time2",
      "description": "获取通道2的高电平时间。",
      "description_en": "Get the high time of channel 2."
    },
    {
      "action_name": "auto-get_period2",
      "description": "获取通道2的周期。",
      "description_en": "Get the period of channel 2."
    },
    {
      "action_name": "auto-get_trigger",
      "description": "获取触发设置。",
      "description_en": "Get the trigger setting."
    },
    {
      "action_name": "auto-get_trigger_source",
      "description": "获取触发源。",
      "description_en": "Get the trigger source."
    },
    {
      "action_name": "auto-get_trigger_edge",
      "description": "获取触发沿。",
      "description_en": "Get the trigger edge."
    }
  ]
}

